solution.js:
const expenses = [
  { label: "Coffee", amount: 450, category: "food" },
  { label: "Train", amount: 1220, category: "travel", receipt: { url: "/r/88.png" } },
  { label: "Lunch", amount: 1350, category: "food", receipt: null },
  { label: "Gift", amount: 5000 },
];

function receiptLabel(expense) {
  return expense.receipt?.url ?? "No receipt";
}

function dailyLimit(settings) {
  return settings?.dailyLimit ?? 5000;
}

function countByCategory(expenses) {
  const counts = new Map();
  for (const e of expenses) {
    const category = e.category ?? "other";
    counts.set(category, (counts.get(category) ?? 0) + 1);
  }
  return counts;
}

function uniqueCategories(expenses) {
  return [...new Set(expenses.map((e) => e.category ?? "other"))];
}

console.log(receiptLabel(expenses[1]), dailyLimit({ dailyLimit: 0 }));
